def taller_within(a: list[int], k: int) -> list[int]:
    if k == 0:
        return [0] * len(a)

    ranks = {value: i + 1 for i, value in enumerate(sorted(set(a)))}
    size = len(ranks)
    tree = [0] * (size + 1)
    result = []

    for i, height in enumerate(a):
        rank = ranks[height]
        count_not_taller = 0
        idx = rank
        while idx:
            count_not_taller += tree[idx]
            idx -= idx & -idx

        result.append(min(i, k) - count_not_taller)

        idx = rank
        while idx <= size:
            tree[idx] += 1
            idx += idx & -idx

        if i >= k:
            idx = ranks[a[i - k]]
            while idx <= size:
                tree[idx] -= 1
                idx += idx & -idx

    return result
